R_API void r_cons_strcat(const char *str) { /* <=== r_cons_strcat */ 
	int len;
	if (!str || I.null) {
		return;
	}
	len = strlen (str);
	if (len > 0) {
		r_cons_memcat (str, len);
	}
}

R_API int r_cons_printf(const char *format, ...) { /* <=== r_cons_printf */ 
	va_list ap;
	if (!format || !*format) {
		return -1;
	}
	va_start (ap, format);
	r_cons_printf_list (format, ap);
	va_end (ap);

	return 0;
}

